def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}
P = {}
P['LY-242'] = ("婚可成但迟：男子自占婚以妻财为用，财两现，取应爻妻财戌土动为主用。戌土子月休囚，然动而化子孙巳火，火生土为回头生，动不为空、化生有力，主对方有意、婚事有根；世爻官鬼酉金临酉日却值旬空（甲戌旬空申酉），世空主本人/男方一时未定、事悬待实。应生世之势在，终局单判为成。应期双层：窗口为本月内出空填实之期，主坐标取酉日后戌日（日档，财逢值兼世出空），单位日，依据填实/逢值路；冲实、逢合两路舍：无冲空主支、合路不与成局同向。置信0.55。", "tradition=liuyao（卡面tradition=liuyao，自占婚）\nsystems_used: liuyao\n用神候选枚举：妻财戌土（应，动）、妻财丑土（初，静）两现；戌动优先、丑静落选记明。旺衰：戌子月休囚，日酉泄，动化巳火回头生补力。世酉金旬空假空待实。动化方向核对：巳火→戌土：生，确认。对象：财应爻即所娶之女，对回占题。列面-证据双闸：列面财动化生、世空；证据世空未出前不断速成，故降为迟成。门类应期对表：婚姻门类查表，首选逢值/填实与候选相合取之。", 0.55, T(di=True, reason="妻财两现（戌动/丑静），取用互比留痕，应验位以动爻戌为主"))
P['LY-243'] = ("婚难成：女家代占以官鬼为夫用，官鬼卯木世爻发动，寅月临旺、日午火泄，动而化兄弟丑土，木入土耗、化退之势，夫星虽旺却动而退泄；应爻妻财亥水动化兄弟戌土，财化兄主中间阻隔、亲友/竞争介入；兄弟丑土三爻又动化财亥，兄财交动、卦乱多动。世应虽有生合之象终被多动冲散，终局单判不成/议而散。应期双层：窗口在本月内，主坐标取卯日后丑日（日档），单位日，依据化退填实路主退散之应；填实成事路与逢值路舍：与终局退散方向相悖。置信0.58。", "tradition=liuyao（女家代占婚）\nsystems_used: liuyao\n代占看用神：官鬼卯木世即所议之婿。旺衰卯寅月旺、日午泄。动化：卯木→丑土耗泄化退，证据链化神土得午日火生非空破，退势成立但按化退权重合判：用神旺而化退权重低本不直断败，然应财化兄、三爻兄动交杂，多动乱局另成阻隔证据，合断难成。动化方向：亥水→戌土被克、丑土→亥水被生逐对核。对象对齐：官世=婿、财应=女家，逐名对回。双闸：列面三动，证据无单一成局链。", 0.58, T(di=True, reason="三爻多动、兄财交动，取用与成局方向存争议留痕"))
P['LY-244'] = ("夫妻终至离散、不和难解：女占夫以官鬼寅木为用，官在二爻静，巳月火旺木休、日亥水生官，官得日生尚存；然世爻子孙申金发动，子孙克官鬼为妻克夫之主象，申金巳月合中带克、动而化妻财亥水，克官之力续存；初爻妻财子水应动化兄弟丑土。子孙旺动克用是断离之纲，终局单判将来分离。近段不和僵持、远段触发为四爻子孙申动克官，指向申金填实之期后分。应期双层：窗口以月计，主坐标取申月（月档），单位月，依据忌神子孙逢值路；冲实/填实路舍：官非空墓无闸门可释。置信0.60。", "tradition=liuyao（女占夫、夫妻不和将来）\nsystems_used: liuyao\n用神官鬼寅木二爻，日亥生、月火泄休。忌神子孙申金世动克官，动化亥水：申金→寅木克，化神亥水→寅木生，逐对核后克官本爻之力为主。两段式：近段僵持、远段离散，远段触发指认申动克官。对象复述：夫=官鬼寅木、占者=世子孙申金，同一性核过。双闸通过。", 0.60, T())
P['LY-245'] = ("有子之望在寅木命之女、且迟得：问何命者有子以子孙为用。子孙卯木应爻静，申月金克木、子孙休囚死，日丑土耗；二爻官鬼丑土发动化出子孙寅木，动爻化出子孙即子息自此路出，寅木即所指之命/子息之支，然寅逢申月冲为月破，化神月破待填实，进退先定：官化子孙方向为子息出现，月破只转应期不否定。终局单判：寅命（寅木）之女可有子。应期双层：窗口以月计，主坐标取寅月（月档，填实月破），单位月，依据填实路；冲实路（申冲寅正犯月破不取）、逢值路同支并入填实不另立。置信0.50。", "tradition=liuyao（问何命之女有子）\nsystems_used: liuyao\n用神子孙：现卦卯木静休囚；变爻子孙寅木由二爻官丑动化出，按变爻优先于伏神取此为子息出处。化神寅木申月月破，决策序先定化出方向再验破，破待填实。动化方向：丑土→寅木被克（土被木克）逐对核。对象：子孙寅即所问何命之答（寅支）。双闸：列面子孙弱，证据只支持迟得一子、不升格。", 0.50, T(di=True, reason="子孙两源（卯静/寅化月破）并列，取变爻源为主留痕"))
P['LY-246'] = ("妻孕平安，胎象偏女：占孕以子孙为胎用，卦中子孙不上卦、妻财亦借变爻见。三爻兄弟申金发动化妻财卯木，申金辰月土生有气、日辰土生，动化卯木；子孙伏藏待考而母象父母两现戌辰静、辰月临月父母旺相护胎，官鬼午火世旺。胎用不现力弱不断男女十分，只以动化卯木柔支、子孙无阳爻发动之象偏断女胎，平安为主断。终局单判平安得女。应期以产期月档论，窗口至临月，主坐标取卯月（月档），单位月，依据化神卯木逢值路；冲实/填实路无空墓闸门舍。置信0.45，胎用伏藏不明故降置信。", "tradition=liuyao（占孕男女兼妻孕平安）\nsystems_used: liuyao\n输入说明：子孙不上卦，伏神宫位卡面未明载，此为输入残损点，basis注明、置信下调，不臆补伏神爻位。父母戌辰辰月旺护胎主平安。兄弟申动化财卯：申金→卯木克、卯为柔支偏女象。对象复述：妻=所孕之人、胎=子孙用神，对回占题。双闸：证据不足以高置信定男女，只定平安与偏女。", 0.45, T(ru=True, di=True, reason="子孙不上卦涉伏神候选且卡面未载伏位，男女判读存疑留痕"))
P['LY-249'] = ("父将归、近日期回：问父何日回以父母为用，父母两现：四爻父母午火、初爻父母巳火。午火子月水克休囚且逢子月冲为月破，然占日庚午，午火临日建，临日月档『逢破不破』、日临即行人近至之象；静卦无动，行人以用神临日为速归。巳火亦子月休囚静伏次位。终局单判归。应期双层：窗口三日内，主坐标取午日次日未日（日档），单位日，依据用神临日逢值路；冲实路（子冲午为月破非出空）舍、填实路午非空不取。置信0.60。对象复述：父=父母午火主用，逐名对回。", "tradition=liuyao（占父远去何日回，行人类）\nsystems_used: liuyao\n用神候选枚举：父母午（四爻）、父母巳（初爻）两现；午临日建胜出定主，巳留应验位次位。决策序：午月破先验旺衰日月，临日建按逢破不破，破转应期。静卦无动化。行人对象复述完成。应期三步日档：近事问何日回，日尺度成立。双闸通过。", 0.60, T(di=True, reason="父母两现（午临日/巳静），取临日者为主用留痕"))
P['LY-250'] = ("夫不直归、先往他处/迟归：妻占夫以官鬼寅木为用，官在二爻静，亥月水生木旺、日甲子水生，官旺相有根主夫无恙；然五爻子孙申金发动克官，申化子孙酉金为化进神，克夫之动进而有力，主有事阻其直归、牵往他方；世父母午火、初爻妻财子水应动化兄弟丑土。终局单判：不即到家，先往他省/他处后归。应期双层：窗口以旬月计，主坐标取寅日（日档偏旬内），单位日，依据用神寅木逢值待子孙申酉之阻先过；冲实路申冲寅为忌神冲用不作归期舍、填实路无空舍。置信0.55。", "tradition=liuyao（妻占夫在外兼何日到，行人类）\nsystems_used: liuyao\n用神官鬼寅木旺相得月日水生。忌神子孙申动化酉：申→寅克，酉→寅克，化进神（申化酉进）逐对核，克力递进主阻归。世午火亥月休、日生。对象复述：夫=官鬼寅木。两段：近段阻往他处、远段逢寅值归，触发为申化酉进神先行。双闸通过。", 0.55, T())
P['LY-251'] = ("子病可愈：占子近病以子孙为用兼官鬼为病。子孙午火四爻静，申月休、日庚寅木生午火，子孙得日生有根；三爻官鬼酉金世发动化子孙午火，鬼化子孙、病化医药/子息，酉金申月旺动化午火回头克（火克金）病神受制而退。原神即子孙得生、忌神官受克，终局单判愈。近段病势在酉金旺时，远段触发官化子孙、应在午火填实。应期双层：窗口五日内，主坐标取午日（日档），单位日，依据子孙逢值/化神填实路；冲实路（午冲子无关本支）舍、冲空路无空舍。置信0.65。", "tradition=liuyao（占子近病，病占）\nsystems_used: liuyao\n用神子孙午火得日寅木生。病神官鬼酉世动化午：酉金→午火被克回头克，午火→酉金克，方向核无误，鬼化子孙主病退。病占对象复述：子=子孙午火。病占原神存续：子孙有根得生非源绝。两段式近危远愈触发已指认。双闸通过。", 0.65, T())
P['LY-252'] = ("子病凶重、难愈：天山遯静卦，子孙不上卦。卦中官鬼午火两现克子孙，父母戌辰、兄弟申两现，子孙水伏藏（乾宫系伏位卡面未明载）。申月金旺、壬子日子水虽为子孙同气临日可作日月分流候选，然官鬼午火四爻世位静而得月生扶之势、病神两现压用，伏用休囚受压、无动爻生扶引拨，飞伏清单多项无用。终局单判凶、近病难愈有危。应期双层：窗口以旬计，主坐标取午日（日档），单位日，依据病神午火逢值危应路；子孙出空/逢值成事路与终局相悖舍。置信0.55，伏位不明降置信。", "tradition=liuyao（占子病，病占）\nsystems_used: liuyao\n输入说明：子孙不上卦、伏神具体爻位卡面未明载，注明残损降置信。候选枚举：现卦无子孙、变爻无（静卦）、日支子水同亲记为候选、伏神候选并列；官鬼午两现为病神压用。飞伏有用六/无用五：伏休囚、无动生、飞压，待出四项至多一项，难出。病占对象复述：子=子孙用神。双闸：列面病神两现，证据支持凶重不直断必死（决策序三类未全齐），故断难愈有危。", 0.55, T(ru=True, di=True, reason="子孙伏藏且日支同亲候选并存，取用存疑留痕"))
P['LY-253'] = ("父病服人参不宜、难见效而助痰之忧：子占父病问服参，父母为父用、亦参药之象所系。父母未土两现，上爻父母未动化父母戌土，寅月卯日木旺双克土，父母休囚死又受日月叠克，动化戌土虽得比助仍在木旺之月无根；子孙亥水四爻静为医药喜神却被土势围、巳火世爻病位。父母衰极而动，主父体元气与药力俱不受。终局单判：服参不好，不宜服。应期不另定愈期，窗口以日内病势计，主坐标取卯日后辰日（日档）见其不应，单位日，依据父母逢值受克路；生扶路无原神旺动舍。置信0.55。", "tradition=liuyao（子占父病问吃人参，病占/医药）\nsystems_used: liuyao\n用神父母未土两现取上爻动者主用，初爻未静留位。旺衰：寅月卯日木克土叠加，休囚无气。动化未→戌同土比助，方向核：土→土比和，非回头生，助力有限不翻衰局。对象复述：父=父母未土、人参之效系于父母药象与子孙亥水医药，逐项对回。决策序第7步：衰+日月克+无救近齐，故断不宜。双闸通过。", 0.55, T(di=True, reason="父母两现（未动/未静）取动者为主留痕"))
P['LY-254'] = ("此医可用、能治：问医可用否以子孙为医药用神。子孙申金世爻，申月临月建旺相、日癸卯木耗有限，子孙旺主药力/医术有力；病神官鬼卯木二爻应动，卯木申月金克休囚、日卯临值，动而化父母巳火，鬼化父母主病转文书/调理，官受子孙旺金所克制；初爻父母巳火动化兄弟未土。子孙临月克病，终局单判医可用、病可治。应期双层：窗口以月计，主坐标取申日后酉日（日档），单位日，依据子孙逢值续旺路；冲实/填实路无空墓舍。置信0.60。", "tradition=liuyao（因杨梅疮占医好否，医药类）\nsystems_used: liuyao\n用神子孙申金世临月建旺相。病神官鬼卯应动化巳：卯木→巳火生（泄病为转），申金→卯木克逐对核。父母巳初动化未土耗。对象：医=子孙申金、病=官鬼卯木，对回。双闸通过。", 0.60, T())
P['LY-255'] = ("修沟从后流不宜、修后亦不助升迁：本例两占并陈。初占火风鼎静卦问沟流宜否，官鬼亥水世、妻财酉金两现，子孙未应；再占火雷噬嗑之无妄，五爻妻财未土世动化官鬼申金，财化官看似官近，然戌月己亥日，未土戌月有气、日亥水克泄，化申金泄土生水、官申金戌月土生却亥日受泄，且初占静卦本象不动为宜。合两占：沟从后流与修沟皆不主吉，修后升迁仍无据。终局单判不宜修、修亦无益。应期不给升迁期，窗口以月计，主坐标取未月（月档）验其无进，单位月，依据世财逢值路；化官成事路因化神受泄降格舍。置信0.50，两占并陈故降置信。", "tradition=liuyao（占衙宇后沟/修沟后如何，宅宇类）\nsystems_used: liuyao\n输入说明：本卡含初占与再占两卦并陈，按两占合参、注明此结构。主用再占世妻财未动化官申：未土→申金泄，申金→亥水日泄，化官不实。初占鼎静卦官亥世主静守。对象：衙宇/沟=所占场所，非人对象定位核过（通则f）。双闸：列面财化官，证据化神受泄故不升格为升迁。", 0.50, T(di=True, reason="一卡两占（初占静卦与再占动卦）合参，结论取舍留痕"))
P['LY-259'] = ("附葬祖茔不宜：以父柩附葬，父母为用不上卦，伏于二爻兄弟辰土之下（坤宫首卦同位推伏，卡面未明载伏位）。初爻妻财子水世发动化兄弟未土，财动克父母、化兄主兄弟/族众阻隔；子月丙申日，父母巳火伏神子月休囚、日申金耗，飞神辰土子月有气压伏，飞伏待出四项至多一项。终局单判不宜附葬、附之不利。应期不给成事期，窗口以月计，主坐标取巳日（日档）验伏父逢值亦只见阻，单位日，依据伏神逢值路；冲飞路辰逢戌冲为候选但伏无力同具不足舍为成事期。置信0.55。", "tradition=liuyao（占父柩附葬祖茔，葬事类）\nsystems_used: liuyao\n输入说明：父母不上卦、伏位卡面未明载，按本宫首卦同位推得并注明，不作直载论。飞伏清单：伏巳火休囚、飞辰土压、无动生伏，待出不成立。财子世动化未：子水→未土被克、财克父象成立逐对核。对象复述：父=伏父母巳火、柩葬之事对回。双闸通过。", 0.55, T(ru=True, reason="父母伏藏取伏神作主用"))
P['LY-301'] = ("妻在家不安、有忧病之象：人在外占妻安否以妻财为用，妻财两现：上爻妻财戌土动、初爻妻财未土世静。寅月乙卯日木旺双克土，财休囚受日月克；上爻戌动与五爻官鬼申金动，本卦豫之否且伏吟之问（卡面标伏吟），动而伏吟主忧闷反复，官申动克木耗土之间接压财，世财未土静受克无援。终局单判不安。应期双层：窗口以旬计，主坐标取戌日（日档），单位日，依据动财逢值见信路；填实路财非空舍、冲实路戌冲辰非本支闸门舍。置信0.60。", "tradition=liuyao（在外占妻安否）\nsystems_used: liuyao\n候选枚举：妻财戌（上动）、妻财未（世静）两现，取动者主用、世财留本人位。旺衰寅月卯日木克土叠加。伏吟结构按卡面所标记入。动化方向：戌、申动化同支（变否栏）按伏吟论忧。对象复述：妻=妻财戌土。双闸通过。日期据卡notes补录寅月乙卯日、空亡子丑，财不空。", 0.60, T(di=True, reason="妻财两现（戌动/未世）取动者为主留痕"))
P['LY-304'] = ("妻病可愈、愈在出空之卯日：占妻病何日愈以妻财卯木为用，妻财卯木三爻静而值旬空（癸丑日空寅卯），午月火泄木休、日丑土耗，用神空而休囚；然四爻子孙亥水发动，亥水午月休、日丑不克，动而生妻财卯木，原神发动来生用神，用神空而有根（根气三项第2项原神生扶成立），假空待出、空只转应期不作凶权。终局单判愈。应期双层：窗口至本旬出空，主坐标取卯日（日档），单位日，依据填实/出空路（旬空最爱填冲）；冲实路寅冲申无关舍、逢值路与填实同支并入不另立。置信0.62。对象复述：妻=妻财卯木。", "tradition=liuyao（占妻病何日愈，病占）\nsystems_used: liuyao\n用神妻财卯木旬空，走真空/假空判别：原神子孙亥动生用，假空判据得生扶成立，判假空待出空。用神空亡根气判读：原神生扶一项成立为有根，空不作凶权。动化亥→申金：水生金为化退于子孙自身不碍生财本爻。病占对象复述完成。应期三步+D四路：实空日首选。双闸通过。", 0.62, T())
P['LY-305'] = ("岳母近病可愈、愈在出空：为岳母占近病以父母酉金为用，父母酉金上爻应静，酉月临月建旺相，然庚辰日空申酉，父母值旬空；临月建之空为假空（旺相有根、得日辰土生扶，假空判据两项以上），空待实不作凶。三爻妻财午火世发动化父母酉金，世动化用、用神自变爻出，近病用神有出路。终局单判可愈。应期双层：窗口至本旬出空，主坐标取酉日（日档），单位日，依据填实/逢值路；冲实路酉冲卯非解法舍。置信0.60。对象复述：岳母=父母酉金，逐名对回。", "tradition=liuyao（占岳母近病，病占）\nsystems_used: liuyao\n用神父母酉金临月建而旬空，走真假空判别：旺相有根+日辰土生扶，判假空。变爻父母酉与现卦同支，世财午动化酉：午火→酉金克为化父母，方向核明。近病尺度日档成立。病占原神：子孙寅木静弱，只以用神本气旺相定愈。双闸通过。", 0.60, T())
P['LY-306'] = ("尸首可见、见在寅日填实之期：占弟尸首以官鬼为用（卡面明定），官鬼寅木二爻静，值旬空（乙巳日空寅卯），子月水生木有气、日巳火泄；静卦无动，鬼用空而得月生为有根之空（坐生旺/月生一项），假空待填实，空主待应主可见而迟。兄弟辰丑两现、妻财亥子两现皆静不夺主。终局单判可见。应期双层：窗口至本旬出空，主坐标取寅日（日档），单位日，依据填实路；冲实路寅冲申为冲用本身不取、逢值路同支并入填实。置信0.50。对象定位：尸首=官鬼寅木，非人对象对回占题（弟已死、所问为尸首）。", "tradition=liuyao（占弟死太湖尸首可见否）\nsystems_used: liuyao\n用神依卡面定官鬼寅木。空亡根气：寅得子月水生为有根，假空待实。静卦无动化、无原神动生。对象对齐表：应验对象为尸首本身不回收到家属。应期三步日档：问何日见以日为尺度。双闸通过。", 0.50, T())
P['LY-307'] = ("有雨、雨在丑日冲未之期：大旱问何日雨以父母为雨用，父母未土两现（世四爻、应初爻）且未为月建，父母临月建旺相、日戊戌土帮身，雨用旺而静，静待冲动；子孙不上卦主晴意弱、妻财卯官鬼巳皆静。旺用静逢冲则发，冲未者丑。终局单判有雨。应期双层：窗口七日内，主坐标取丑日（日档），单位日，依据冲用神之支路（冲起）；填实路父母非空舍、逢值路未日为再值不如冲动速舍。置信0.55。", "tradition=liuyao（大旱占何日有雨，天时类）\nsystems_used: liuyao\n用神父母未土两现同支临月建，取世位为主、应位同支并记。旺相临月、日土帮。静卦待冲：D项冲起扫查得丑冲未一路首选。对象：雨=父母未土。双闸通过。日辰据卡notes为戊戌日、空辰巳，父母不空。", 0.55, T(di=True, reason="父母两现同支（世/应）取世位为主留痕"))
P['LY-309'] = ("将来有官但迟远、年月方见：问将来有官否以官鬼为用兼父母为印。官鬼巳火初爻动，亥月水克火休囚、日己丑土泄，巳逢亥月冲为月破，官动而破；化妻财寅木，寅得亥月合生（亥寅合）化神有救，官化财主先财后官/由财路得官。上爻父母未土世动值旬空（己丑空午未）化父母戌土，印空待实。官破待填、印空待出，终局单判有官而迟。应期双层：窗口以年计，主坐标取寅年（年档），单位年，依据化神寅木逢值合生路；月破填实路取巳月为次候选入reasoning舍（尺度为将来远问年档优先）、出空路未年同为候选舍于寅年合流之后。置信0.50。", "tradition=liuyao（占将来有官否，仕途类）\nsystems_used: liuyao\n用神官鬼巳火月破先验：动而破、化寅木得月合，破转应期。父母未世动空化戌，印待实。动化方向：巳火→寅木被生（木生火回头生于化神生本爻）逐对核为回头生，官有救。应期尺度通则：远期仕途定年档先年后月。双闸：列面官破印空，证据化神合生只支持迟得不升格速得。", 0.50, T(di=True, reason="官破与印空双闸门并存，应期候选对决留痕"))
P['LY-311'] = ("子病凶危、难愈：占子病以子孙申金为用，子孙申金三爻应发动，寅月冲申为月破，日甲午火克金，子孙月破又受日克；动化父母午火，午火克申金为回头克，化神午火寅月得生有力，用神动而化回头克且破；二爻父母午火又动化兄弟辰土，父母动叠克子孙（医药/长辈之力反压）。用神休囚、破、化回头克三项叠加无原神生扶（妻财子水静弱），决策序终局三类近齐。终局单判凶危难愈。应期双层：窗口以旬计，主坐标取午日（日档）危应，单位日，依据忌神父母午火逢值路；子孙填实申日成事路与终局相悖舍。置信0.65。对象复述：子=子孙申金。", "tradition=liuyao（占子病吉凶，病占）\nsystems_used: liuyao\n用神子孙申金月破+日克+动化父母午回头克，动化方向核：申金→午火被克确认，午火寅月生旺克力有据。父母午二爻动叠压。真假空：申不空论破。病占两段：近段即危、远段无指向转愈之动化触发，明言一段终局远段无据不报之外的危局即终局。双闸通过。", 0.65, T())
for cid, (txt, basis, conf, trig) in P.items():
    obj = {"case_id": cid, "prediction_text": txt, "basis": basis, "confidence": conf, "trigger": trig}
    (OUT / f"{cid}.json").write_text(json.dumps(obj, ensure_ascii=False, indent=2), encoding="utf-8")
    print("wrote", cid)
